resource originGroup 'Microsoft.Cdn/profiles/originGroups@2023-05-01' = {
  parent: frontDoorProfile
  name: 'checkout-origins'
  properties: {
    loadBalancingSettings: { sampleSize: 4, successfulSamplesRequired: 3, additionalLatencyInMilliseconds: 50 }
    healthProbeSettings: { probePath: '/health/ready', probeProtocol: 'Https', probeIntervalInSeconds: 30 }
    trafficRestorationTimeToHealedOrNewEndpointsInMinutes: 5
  }
}

resource originStable 'Microsoft.Cdn/profiles/originGroups/origins@2023-05-01' = {
  parent: originGroup
  name: 'stable'
  properties: {
    hostName: 'app-quotient-prod.azurewebsites.net'
    httpPort: 80
    httpsPort: 443
    priority: 1
    weight: 950            // 95% of traffic
    enabledState: 'Enabled'
  }
}

resource originCanary 'Microsoft.Cdn/profiles/originGroups/origins@2023-05-01' = {
  parent: originGroup
  name: 'canary'
  properties: {
    hostName: 'app-quotient-prod-staging.azurewebsites.net'
    httpPort: 80
    httpsPort: 443
    priority: 1
    weight: 50             // 5% of traffic
    enabledState: 'Enabled'
  }
}
